// 브레이크포인트 1개 > 로그 10개 (멈춰서 모든 상태를 봄)

// 로그를 쓸 때는 유니크 접두어 — 나중에 한 번에 지운다
console.trace('[DBG-a4f2] 여기서 누가 부르나');   // 호출 스택

// 객체가 언제 바뀌는지 모를 때 — Proxy 로 변경 추적
const watched = new Proxy(obj, {
  set(target, key, value) {
    console.trace(`[DBG-a4f2] ${String(key)} = ${value} 로 바뀜`);
    target[key] = value; return true;
  },
});
// 나중에: grep "[DBG-a4f2]" 로 전부 찾아 삭제 (코드에 안 남김)

// 1) 회귀 테스트를 먼저 (실패하는 빨강) — 최소 재현이 그대로 테스트
test('빈 입력이면 크래시 안 남 (버그 #123)', () => {
  expect(() => process('')).not.toThrow();   // 지금은 실패(빨강)
});
// 2) 고쳐서 초록으로 → 정말 고쳤음 확인 + 회귀 방지

// 3) 「왜 이 버그가 검사에 안 걸렸나」 한 줄
//    → 빈 입력 엣지 케이스 테스트가 없었다 → 그 부류를 막는다

